-- ==========================================================================
-- COMPLETE SUPABASE POSTGRESQL SCHEMA WITH FULL PGVECTOR EMBEDDINGS
-- ==========================================================================

CREATE EXTENSION IF NOT EXISTS vector;

-- Drop previous partial tables for a clean, fresh setup
DROP TABLE IF EXISTS query_logs CASCADE;
DROP TABLE IF EXISTS document_chunks CASCADE;
DROP TABLE IF EXISTS documents CASCADE;
DROP TABLE IF EXISTS agent_prompts CASCADE;
DROP TABLE IF EXISTS users CASCADE;

CREATE TABLE IF NOT EXISTS users (
    id VARCHAR PRIMARY KEY,
    name VARCHAR NOT NULL,
    email VARCHAR UNIQUE NOT NULL,
    password_hash VARCHAR NOT NULL,
    role VARCHAR DEFAULT 'employee',
    department VARCHAR DEFAULT 'general',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS documents (
    id VARCHAR PRIMARY KEY,
    filename VARCHAR NOT NULL,
    department VARCHAR DEFAULT 'general',
    access_level VARCHAR DEFAULT 'employee',
    uploaded_by VARCHAR REFERENCES users(id) ON DELETE SET NULL,
    uploaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    chunks_count INTEGER DEFAULT 0
);

CREATE TABLE IF NOT EXISTS document_chunks (
    id VARCHAR PRIMARY KEY,
    document_id VARCHAR REFERENCES documents(id) ON DELETE CASCADE,
    source VARCHAR NOT NULL,
    department VARCHAR DEFAULT 'general',
    access_level VARCHAR DEFAULT 'employee',
    text TEXT NOT NULL,
    chunk_index INTEGER DEFAULT 0,
    embedding vector(384)
);

CREATE TABLE IF NOT EXISTS agent_prompts (
    id VARCHAR PRIMARY KEY,
    name VARCHAR NOT NULL,
    system_prompt TEXT NOT NULL,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS query_logs (
    id VARCHAR PRIMARY KEY,
    user_id VARCHAR REFERENCES users(id) ON DELETE SET NULL,
    query VARCHAR NOT NULL,
    agent VARCHAR DEFAULT 'general',
    confidence_score INTEGER DEFAULT 0,
    hallucination_detected BOOLEAN DEFAULT FALSE,
    tokens_used INTEGER DEFAULT 0,
    user_feedback INTEGER DEFAULT 0,
    context_relevance_score INTEGER DEFAULT 0,
    faithfulness_score INTEGER DEFAULT 0,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- INDEXES FOR FAST DEPARTMENT FILTERING
CREATE INDEX IF NOT EXISTS idx_docs_department ON documents(department);
CREATE INDEX IF NOT EXISTS idx_docs_access ON documents(access_level);
CREATE INDEX IF NOT EXISTS idx_chunks_department ON document_chunks(department);
CREATE INDEX IF NOT EXISTS idx_chunks_access ON document_chunks(access_level);
CREATE INDEX IF NOT EXISTS idx_chunks_doc_id ON document_chunks(document_id);

