INSERT INTO document_chunks (id, document_id, source, department, access_level, text, chunk_index, embedding) VALUES ('1a244782-d17e-4541-995c-6ca165b6e652', '2fe58f48-ef79-4b88-a45f-3cffef19294b', 'HR_Leave_Policy.txt', 'hr', 'employee', 'EMERGENCY LEAVE
2 days emergency leave per year for immediate family emergencies.
Emergency leave requires approval from the direct manager and HR.

UNPAID LEAVE
